      eapply (apb_case regs mem rom sp w can PH Hw R1 R2 R11
                (fst (fst res)) (snd (fst res)) (snd res) (fst (fst car)) (snd car));
      [ vm_cast_no_check (@eq_refl _ res)
      | reflexivity
      | vm_compute; reflexivity
      | vm_compute; reflexivity
      | vm_cast_no_check (@eq_refl _ car)
      | vm_compute; reflexivity
      | vm_compute; reflexivity
      | vm_compute; reflexivity
      | vm_compute; reflexivity
      | vm_compute; reflexivity ]
  end.

