Theorem aprintf0_buffered `{fx : DFP} : forall (j : nat) regs mem rom (sp : word) (can : Z),
  (j <= 2)%nat ->
  apbH mem sp (ABUF + 2 * Z.of_nat j) can ->
  getr regs 1 = Z_to_bv 64 0xe87a0 -> getr regs 2 = sp -> getr regs 11 = Z_to_bv 64 0 ->
  exists regs' mem',
    msteps RSEGS (mkst regs (Z_to_bv 64 0xe884c) mem rom) (mkst regs' (Z_to_bv 64 0xe87a0) mem' rom)
    /\ keeps_cs regs regs'
    /\ frame_mod mem mem' [(Z_to_bv 64 (bv_unsigned sp - 3400), 3400); (Z_to_bv 64 0x189b00, 4);
                          (Z_to_bv 64 0x189b28, 8); (Z_to_bv 64 (ABUF + 2 * Z.of_nat j), 2)]
    /\ rdn RSEGS mem' (Z_to_bv 64 (ABUF + 2 * Z.of_nat j)) 2 = Some [Z_to_bv 8 0x30; Z_to_bv 8 0x0a]
    /\ rdn RSEGS mem' (Z_to_bv 64 0x189b28) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (ABUF + 2 * Z.of_nat j + 2)))
